sql.company.getCompaniesAvailableForUser:

select id, company_name from flow.company_hierarchy_filter_down((select c1.id
 from (
     select min(level) as level
     from flow.company c
             inner join flow.user_company uc on uc.company_id = c.id
     where user_id = :userId
    ) as foo
    inner join flow.company c1 on c1.level = foo.level
    inner join flow.user_company uc1 on uc1.company_id = c1.id and uc1.user_id = 2350555
limit 1));
